export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const ids = {};
  (Array.isArray(inputs.eventIds) ? inputs.eventIds : []).forEach((id) => { ids[str(id)] = true; });
  // Пришёл = непустой checked_in_at (DATA-MODEL), статус не смотрим: строка,
  // отменённая после чекина, всё равно означает «был». Дедуп пар (ADR-0003).
  const seen = {};
  const targets = arr(inputs.regs).map(flat)
    .filter((r) => ids[str(r.event_id)] && str(r.telegram_id) !== '' && str(r.checked_in_at) !== '' && str(r.checked_in_at) !== '-')
    .filter((r) => { const k = str(r.event_id) + '|' + str(r.telegram_id); if (seen[k]) return false; seen[k] = true; return true; })
    .map((r) => ({ telegramId: str(r.telegram_id), chatId: str(r.telegram_id), eventId: str(r.event_id) }));
  return { targets: targets, count: targets.length };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = { __recordId: String(rec && rec.id ? rec.id : '') };
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  // Tables отдаёт DATE строкой и зону не гарантирует — без зоны это UTC (OWN-3).
  const parse = (s) => { if (!s) return NaN; return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z'); };

  const now = Date.now();
  const nowIso = new Date(now).toISOString();
  const rows = arr(inputs.events).map(flat);

  // Только вперёд (OWN-4): published→finished. cancelled/finished/draft не трогаем.
  // Пустой ends_at — пропуск. Диапазон по DATE в фильтрах не работает (Q15),
  // поэтому чтение берёт published+finished широким фильтром, а сравнение здесь.
  const due = rows
    .filter((e) => str(e.status) === 'published' && str(e.id) !== '')
    .filter((e) => { const ms = parse(str(e.ends_at)); return isFinite(ms) && ms <= now; })
    .map((e) => ({ recordId: str(e.__recordId), id: str(e.id) }))
    .filter((x) => x.recordId !== '');
  // Catch-up — короткий хвост для позднего чекина сразу после финиша: событие
  // уже finished, а отметка появилась позже. Отсчёт — от finished_at (его
  // ставит сам lifecycle), не от ends_at: иначе окно тянется 48 ч и каждый тик
  // зовёт reg-afterword по всем пришедшим (~192 лишних вызова на человека),
  // хотя callee всё равно дедупит. Верхняя граница — 2 тика крона */15.
  const CATCHUP_MS = 2 * 15 * 60 * 1000;
  const catchup = rows
    .filter((e) => str(e.status) === 'finished' && str(e.id) !== '')
    .filter((e) => {
      const fin = parse(str(e.finished_at));
      const ms = isFinite(fin) ? fin : parse(str(e.ends_at));
      return isFinite(ms) && ms >= now - CATCHUP_MS;
    })
    .map((e) => str(e.id));
  const seen = {};
  const finishedIds = due.map((x) => x.id).concat(catchup)
    .filter((id) => { if (seen[id]) return false; seen[id] = true; return true; });
  // Сентинел вместо пустого `in`: пустое значение валит чтение (fail-closed),
  // а несуществующий id возвращает ноль строк.
  return { nowIso: nowIso, due: due, dueCount: due.length, finishedIds: finishedIds, finishedIdsCsv: finishedIds.length ? finishedIds.join(',') : '__none__' };
};
